UPDATE courses SET
    course_description = '<h4>Course Intro</h4><h3>Course Overview</h3> <p>This qualification is tailored for those looking to take on leadership roles in the kitchen, such as Chef de Partie, Sous Chef, or Kitchen Manager. Throughout the course, you will master the essentials of kitchen operations, from food preparation and menu planning to staff management and financial oversight. You will also cover important topics like food safety, sustainability in the kitchen, and advanced cooking techniques.</p> <p>Students will gain skills in managing kitchen operations efficiently, focusing on producing high-quality food while maintaining profitability and adhering to food safety regulations. The curriculum also covers customer service, communication, and conflict resolution, preparing students to lead kitchen teams and collaborate effectively with staff and customers.</p><h4>Career Outcomes</h4><p>Elevate your culinary career with our comprehensive training program. Gain a deep understanding of culinary techniques and management principles. Choose between day or evening classes to fit your lifestyle. Benefit from real-world experience through 360 hours of industry placements. Network with industry professionals and develop the skills needed to excel in high-pressure culinary environments.</p><h4>Course Structure</h4><table border="1" cellpadding="0" cellspacing="0"> <tbody> <tr> <td colspan="4" rowspan="1"><strong>SIT40521 Certificate IV In kitchen Management</strong></td> </tr> <tr> <td>Unit No</td> <td>Unit code</td> <td>Unit name</td> <td>Unit Type</td> </tr> <tr> <td>1</td> <td>BSBTWK501</td> <td>Lead Diversity and Inclusion</td> <td>Elective</td> </tr> <tr> <td>2</td> <td>SITXCOM010</td> <td>Manage Conflict</td> <td>Core</td> </tr> <tr> <td>3</td> <td>SITXWHS006</td> <td>Identify Hazards, Assess and Control Safety Risks</td> <td>Elective</td> </tr> <tr> <td>4</td> <td>SITXWHS007</td> <td>Implement And Monitor Work Health and Safety Practices</td> <td>Core</td> </tr> <tr> <td>5</td> <td>SITXHRM008</td> <td>Roster Staff</td> <td>Core</td> </tr> <tr> <td>6</td> <td>SITXHRM009</td> <td>Lead And Manage People</td> <td>Core</td> </tr> <tr> <td>7</td> <td>SITXMGT004</td> <td>Monitor Work Operations</td> <td>Core</td> </tr> <tr> <td>8</td> <td>SITXFIN009</td> <td>Manage Finances Within a Budget</td> <td>Core</td> </tr> <tr> <td>9</td> <td>SITXFSA005</td> <td>Use Hygienic Practices for Food Safety</td> <td>Core</td> </tr> <tr> <td>10</td> <td>SITXFSA006</td> <td>Participate In Safe Food Handling Practices</td> <td>Core</td> </tr> <tr> <td>11</td> <td>SITXFSA008</td> <td>Develop And Implement a Food Safety Program</td> <td>Core</td> </tr> <tr> <td>12</td> <td>SITHCCC023</td> <td>Use Food Preparation Equipment</td> <td>Core</td> </tr> <tr> <td>13</td> <td>SITXINV006</td> <td>Receive, Store and Maintain Stock</td> <td>Core</td> </tr> <tr> <td>14</td> <td>SITHCCC027</td> <td>Prepare Dishes Using Basic Methods of Cookery</td> <td>Core</td> </tr> <tr> <td>15</td> <td>SITHCCC029</td> <td>Prepare Stocks, Sauces and Soups</td> <td>Core</td> </tr> <tr> <td>16</td> <td>SITHCCC030</td> <td>Prepare Vegetable, Fruit, Eggs and Farinaceous Dishes</td> <td>Core</td> </tr> <tr> <td>17</td> <td>SITHCCC028</td> <td>Prepare Appetisers and Salads</td> <td>Core</td> </tr> <tr> <td>18</td> <td>SITHCCC031</td> <td>Prepare Vegetarian and Vegan Dishes</td> <td>Core</td> </tr> <tr> <td>19</td> <td>SITHCCC035</td> <td>Prepare Poultry Dishes</td> <td>Core</td> </tr> <tr> <td>20</td> <td>SITHCCC036</td> <td>Prepare Meat Dishes</td> <td>Core</td> </tr> <tr> <td>21</td> <td>SITHCCC037</td> <td>Prepare Seafood Dishes</td> <td>Core</td> </tr> <tr> <td>22</td> <td>SITHCCC040</td> <td>Prepare and Serve Cheese</td> <td>Elective</td> </tr> <tr> <td>23</td> <td>SITHCCC041</td> <td>Produce Cakes, Pastries and Breads</td> <td>Core</td> </tr> <tr> <td>24</td> <td>SITHPAT016</td> <td>Produce Desserts</td> <td>Core</td> </tr> <tr> <td>25</td> <td>SITHFAB025</td> <td>Prepare And Serve Espresso Coffee</td> <td>Elective</td> </tr> <tr> <td>26</td> <td>SITHCCC038</td> <td>Produce And Serve Food for Buffets</td> <td>Elective</td> </tr> <tr> <td>27</td> <td>SITHCCC026</td> <td>Package Prepared Foodstuffs</td> <td>Elective</td> </tr> <tr> <td>28</td> <td>SITHCCC042</td> <td>Prepare Food to Meet Special Dietary Requirements</td> <td>Core</td> </tr> <tr> <td>29</td> <td>SITHCCC043</td> <td>Work Effectively As A Cook</td> <td>Core</td> </tr> <tr> <td>30</td> <td>SITHKOP013</td> <td>Plan Cooking Operations</td> <td>Core</td> </tr> <tr> <td>31</td> <td>SITHKOP010</td> <td>Plan And Cost Recipes</td> <td>Core</td> </tr> <tr> <td>32</td> <td>SITHKOP015</td> <td>Design And Cost Menus</td> <td>Core</td> </tr> <tr> <td>33</td> <td>SITHKOP012</td> <td>Develop Recipes For Special Dietary Requirements</td> <td>Core</td> </tr> </tbody> </table><h4>Pathway</h4><ul> <li>Advanced Diploma of Hospitality Management</li> <li>Bachelor of Culinary Arts or Hospitality Management</li> <li>Specialized short courses in areas such as Food Safety and Hygiene or Menu Development</li> <li>Professional certifications in areas such as Nutrition or Kitchen Safety</li> </ul>',
