    entry_requirements = '<h4>Entry Requirements</h4><p>﻿There are no specific prerequisites specified in the training package for this kitchen management course in Australia. </p> <p><strong>RTO Requirements for International Students </strong></p> <p>To be eligible for enrolment at APC into the Certificate IV in Kitchen Management all international applicants must be 18 years old or older and exhibit evidence of academic and English language proficiency as follows:</p> <p><strong>Academic Requirements:</strong></p> <p>✅ Successful completion of Year 12 or equivalent</p> <p>English Language Requirements:</p> <p>✅ Be competent in written and spoken English with an IELTS Score of no less than 6.0 or equivalent language test score.</p>',
    apply_form = 'https://australianpolytechnic.edu.au/courses/certificate-iv-in-kitchen-management',
    updated_at = NOW()
WHERE cricos_course_code = '115307C';
UPDATE courses SET
    course_description = '<h4>Course Intro</h4><p>The Diploma of Hospitality Management is a comprehensive program that covers a wide range of critical skills required for managing various hospitality businesses. Throughout the course, you will learn to manage and operate hospitality services, develop and lead a team, plan and control finances, and deliver exceptional customer service.</p> <p>The course combines theoretical knowledge with practical experience, ensuring you are job-ready upon completion. Students are also required to complete a minimum of 12 service shifts, giving them real-world experience in hospitality environments.</p><h4>Career Outcomes</h4><p>1. Hands-on Experience: With a requirement of 12 service shifts, this course ensures that you have real-world, practical experience that can be directly applied to future roles.<br/> 2. Industry-Relevant Curriculum: The course content is designed in consultation with industry professionals.</p><h4>Course Structure</h4><table cellspacing="0"> <tbody> <tr> <td><strong>SIT50422 Diploma of Hospitality Management</strong></td> </tr> <tr> <td><strong>Core Units</strong></td> </tr> <tr> <td>SITXCCS015 Enhance customer service experiences</td> </tr> <tr> <td>SITXCCS016 Develop and manage quality customer service practices</td> </tr> <tr> <td>SITXCOM010 Manage conflict</td> </tr> <tr> <td>SITXFIN009 Manage finances within a budget</td> </tr> <tr> <td>SITXFIN010 Prepare and monitor budgets</td> </tr> <tr> <td>SITXGLC002 Identify and manage legal risks and comply with law</td> </tr> <tr> <td>SITXHRM008 Roster staff</td> </tr> <tr> <td>SITXHRM009 Lead and manage people</td> </tr> <tr> <td>SITXMGT004 Monitor work operations</td> </tr> <tr> <td>SITXMGT005 Establish and conduct business relationships</td> </tr> <tr> <td>SITXWHS007 Implement and monitor work health and safety practices</td> </tr> <tr> <td><strong>Elective Units</strong></td> </tr> <tr> <td>SITXFSA005 Use hygienic practices for food safety</td> </tr> <tr> <td>SITHKOP013 Plan cooking operations</td> </tr> <tr> <td>SITHCCC023 Use food preparation equipment</td> </tr> <tr> <td>SITHCCC027 Prepare dishes using basic methods of cookery</td> </tr> <tr> <td>SITHCCC028 Prepare appetisers and salads</td> </tr> <tr> <td>SITHCCC029 Prepare stocks, sauces and soups</td> </tr> <tr> <td>SITHCCC030 Prepare vegetable, fruit, eggs and farinaceous dishes</td> </tr> <tr> <td>SITHCCC035 Prepare poultry dishes</td> </tr> <tr> <td>SITHCCC036 Prepare meat dishes</td> </tr> <tr> <td>SITHCCC037 Prepare seafood dishes</td> </tr> <tr> <td>SITHIND006 Source and use information on the hospitality industry</td> </tr> <tr> <td>SITHPAT016 Produce desserts</td> </tr> <tr> <td>SITXFSA006 Participate in safe food handling practices</td> </tr> <tr> <td>BSBCMM411 Make presentations</td> </tr> <tr> <td>SITXFIN008 Interpret financial information</td> </tr> <tr> <td>SITXHRM010 Recruit, select and induct staff</td> </tr> <tr> <td>SITXHRM007 Coach others in job skills</td> </tr> </tbody> </table><h4>Pathway</h4><ul> <li>Advanced Diploma of Hospitality Management</li> <li>Bachelor of Hospitality Management</li> <li>Specialized short courses in areas such as Event Management or Revenue Management</li> <li>Professional certifications in Food Safety and Hygiene</li> </ul>',
