UPDATE courses SET
    course_description = '<h4>Course Intro</h4><h1>Course Introduction</h1> <p>The SIT60322 Advanced Diploma of Hospitality Management is designed for individuals seeking to advance into senior leadership or managerial roles within the hospitality industry. This qualification provides students with the in-depth knowledge and practical expertise needed to oversee hospitality operations in a range of settings, including hotels, resorts, restaurants, event venues, and other service-based environments. It is ideal for those aspiring to become hospitality managers, operations directors, or business owners in the industry.</p> <p>Throughout the course, students will develop critical skills in managing hospitality services, coordinating staff and departments, and implementing strategies to enhance customer experiences. The program covers key areas such as financial management, budgeting, human resource planning, marketing, business planning, and legal compliance. Students will also learn how to manage diversity, drive workplace innovation, and ensure quality service delivery across various hospitality functions.</p> <p>In addition to operational competencies, the course fosters essential leadership, communication, and strategic decision-making abilities needed to lead dynamic teams and respond effectively to challenges within fast-paced and customer-focused environments. Emphasis is placed on sustainability, workplace health and safety, conflict resolution, and aligning operations with organisational goals and industry standards.</p> <p>Upon successful completion, graduates will be equipped to pursue high-level roles in the hospitality sector, manage entire establishments, or take the next step toward owning and operating a hospitality business. This qualification also serves as a strong foundation for further study in business or management disciplines.</p><h4>Course Structure</h4><h2>SIT60322 Advanced Diploma of Hospitality Management</h2> <table> <tbody> <tr> <th>No</th> <th>Unit Code</th> <th>Unit Name</th> <th>Unit Type</th> </tr> <tr> <td>1</td> <td>SITXWHS008</td> <td>Establish and maintain a work health and safety system</td> <td>Core</td> </tr> <tr> <td>2</td> <td>BSBFIN601</td> <td>Manage organisational finances</td> <td>Core</td> </tr> <tr> <td>3</td> <td>SITXHRM012</td> <td>Monitor staff performance</td> <td>Core</td> </tr> <tr> <td>4</td> <td>BSBOPS502</td> <td>Manage business operational plans</td> <td>Elective (Group D)</td> </tr> <tr> <td>5</td> <td>SITXMPR014</td> <td>Develop and implement marketing strategies</td> <td>Core</td> </tr> <tr> <td>6</td> <td>SITXFIN011</td> <td>Manage physical assets</td> <td>Core</td> </tr> <tr> <td>7</td> <td>BSBOPS601</td> <td>Develop and implement business plans</td> <td>Core</td> </tr> <tr> <td>8</td> <td>BSBOPS504</td> <td>Manage business risk</td> <td>Elective (Group D)</td> </tr> <tr> <td>9</td> <td>SITXCCS016</td> <td>Develop and manage quality customer service practices</td> <td>Core</td> </tr> <tr> <td>10</td> <td>SITXMGT005</td> <td>Establish and conduct business relationships</td> <td>Core</td> </tr> <tr> <td>11</td> <td>SITXFIN010</td> <td>Prepare and monitor budgets</td> <td>Core</td> </tr> <tr> <td>12</td> <td>SITXHRM010</td> <td>Recruit, select and induct staff</td> <td>Core</td> </tr> <tr> <td>13</td> <td>SITXGLC002</td> <td>Identify and manage legal risks and comply with law</td> <td>Core</td> </tr> <tr> <td>14</td> <td>SITXFIN009</td> <td>Manage finances within a budget</td> <td>Core</td> </tr> <tr> <td>15</td> <td>SITXMGT004</td> <td>Monitor work operations</td> <td>Core</td> </tr> <tr> <td>16</td> <td>SITXHRM009</td> <td>Lead and manage people</td> <td>Core</td> </tr> <tr> <td>17</td> <td>SITXFSA005</td> <td>Use hygienic practices for food safety</td> <td>Elective (Group A)</td> </tr> <tr> <td>18</td> <td>SITXFSA006</td> <td>Participate in safe food handling practices</td> <td>Elective (Group C)</td> </tr> <tr> <td>19</td> <td>SITXFSA008</td> <td>Develop and implement a food safety program</td> <td>Elective (Group C)</td> </tr> <tr> <td>20</td> <td>SITHCCC027</td> <td>Prepare dishes using basic methods of cookery</td> <td>Elective (Group C)</td> </tr> <tr> <td>21</td> <td>SITHCCC028</td> <td>Prepare appetisers and salads</td> <td>Elective (Group C)</td> </tr> <tr> <td>22</td> <td>SITHCCC029</td> <td>Prepare stocks, sauces and soups</td> <td>Elective (Group C)</td> </tr> <tr> <td>23</td> <td>SITHCCC030</td> <td>Prepare vegetable, fruit, eggs and farinaceous dishes</td> <td>Elective (Group C)</td> </tr> <tr> <td>24</td> <td>SITHCCC031</td> <td>Prepare vegetarian and vegan dishes</td> <td>Elective (Group C)</td> </tr> <tr> <td>25</td> <td>SITHCCC035</td> <td>Prepare poultry dishes</td> <td>Elective (Group C)</td> </tr> <tr> <td>26</td> <td>SITHCCC036</td> <td>Prepare meat dishes</td> <td>Elective (Group C)</td> </tr> <tr> <td>27</td> <td>SITHCCC037</td> <td>Prepare seafood dishes</td> <td>Elective (Group C)</td> </tr> <tr> <td>28</td> <td>SITHCCC040</td> <td>Prepare and serve cheese</td> <td>Elective (Group C)</td> </tr> <tr> <td>29</td> <td>SITHCCC041</td> <td>Produce cakes, pastries and breads</td> <td>Elective (Group C)</td> </tr> <tr> <td>30</td> <td>SITHPAT016</td> <td>Produce desserts</td> <td>Elective (Group C)</td> </tr> <tr> <td>31</td> <td>SITHCCC026</td> <td>Package prepared foodstuffs</td> <td>Elective (Group C)</td> </tr> <tr> <td>32</td> <td>SITHCCC042</td> <td>Prepare food to meet special dietary requirements</td> <td>Elective (Group C)</td> </tr> <tr> <td>33</td> <td>SITHKOP013</td> <td>Plan cooking operations</td> <td>Elective (Group B)</td> </tr> </tbody> </table><h4>Pathway</h4><h2><strong>Career Opportunity</strong></h2> <p><strong>Upon completion of the Advanced Diploma of Hospitality Management, graduates can pursue a wide range of senior career pathways within the hospitality industry, including:</strong></p> <ul> <li><strong>Hospitality Manager</strong> – Oversee the daily operations of hotels, resorts, or restaurants, ensuring service quality, guest satisfaction, and staff performance meet organisational standards.</li> <li><strong>Food and Beverage Manager</strong> – Manage the planning, delivery, and profitability of food and beverage services, including menu development, supplier negotiation, and customer service excellence.</li> <li><strong>Operations Manager (Hospitality)</strong> – Coordinate multiple departments within a hospitality venue, ensuring smooth and efficient service delivery across all functions.</li> <li><strong>Restaurant or Venue Manager</strong> – Lead and manage restaurant or event venue operations, supervising staff, maintaining quality control, and ensuring compliance with health and safety regulations.</li> <li><strong>Front Office or Rooms Division Manager</strong> – Manage guest services, reservations, and front office procedures, ensuring a seamless customer experience from check-in to check-out.</li> <li><strong>Events or Functions Manager</strong> – Plan and oversee hospitality events, including conferences, weddings, and corporate functions, managing logistics, vendors, and client relations.</li> <li><strong>Business Owner or Entrepreneur</strong> – Establish and operate a hospitality-based business such as a café, catering company, or boutique hotel.</li> </ul> <p>Graduates may also use this qualification as a pathway to further study in business or hospitality management at a university level, or to meet experience requirements for senior industry roles in Australia and internationally.</p> <p> </p>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = 20000,
    enrolment_fee = 250,
    materials_fee = 1500,
    entry_requirements = '<h4>Entry Requirements</h4><h2><strong>Course Entry Requirements</strong></h2> <p><strong>Training Package Requirements</strong></p> <p>Prior to commencing this qualification, an individual must have completed one of the following qualifications (or equivalent):</p> <ul> <li><strong>SIT50422 Diploma of Hospitality Management</strong>, or</li> <li><strong>its superseded version SIT50416 Diploma of Hospitality Management</strong>,</li> <li><strong>or an equivalent qualification</strong>,<br/> provided that the listed elective unit <strong>SITXFIN009 Manage finances within a budget</strong> (or equivalent) has been completed by those seeking to enrol.</li> </ul> <p><strong>RTO Requirements for International Students</strong></p> <p>To be eligible for enrolment at APC into the SIT60322 Advanced Diploma of Hospitality Management, all international applicants must be 18 years old or older and exhibit evidence of academic and English language proficiency as follows:</p> <p><strong>Academic Requirements:</strong></p> <p>✅ Successful completion of Year 12 or equivalent</p> <p><strong>English Language Requirements:</strong></p> <p>✅ Be competent in written and spoken English with an IELTS Score of no less than 6.0 or an equivalent language test score.</p>',
    apply_form = 'https://australianpolytechnic.edu.au/courses/SIT60322 Advanced Diploma of Hospitality Management',
    updated_at = NOW()
WHERE cricos_course_code = '117773E';
UPDATE courses SET
    course_description = '<h4>Course Intro</h4><h1>Course Introduction</h1> <p>The CPC50220 Diploma of Building and Construction (Building) is designed for individuals aiming to progress into supervisory or management roles within the building and construction industry. This qualification equips students with the advanced knowledge and practical skills required to plan, coordinate, and manage residential and commercial building projects from start to finish. It is ideal for those who aspire to become licensed builders, site managers, construction supervisors, or project managers.</p> <p>Throughout the course, students will develop expertise in interpreting and applying building codes and standards, preparing and evaluating project tenders, managing construction contracts, and overseeing on-site operations. The program also emphasizes key areas such as structural principles, construction technology, building and site surveying, cost estimation, and project scheduling. Students will gain the ability to effectively manage resources, budgets, timelines, and personnel to ensure construction projects are completed safely, efficiently, and to the highest quality standards.</p> <p>In addition to technical competencies, the course fosters essential leadership and communication skills needed to manage teams, liaise with clients and stakeholders, resolve conflicts, and make informed decisions under pressure. Workplace health and safety, risk management, sustainability practices, and legal compliance are also central components of the curriculum, preparing graduates for the regulatory responsibilities associated with construction management roles.</p> <p>Upon successful completion, students will be well-prepared to pursue licensing and registration (subject to local requirements) and take on advanced roles within the building and construction sector, contributing to the delivery of structurally sound, environmentally responsible, and commercially viable construction projects.</p> <h4>Course Structure</h4><div> <table cellspacing="0"> <thead> <tr> <td colspan="4"><strong>CPC50220 Diploma of Building and Construction (Building)</strong></td> </tr> </thead> <tbody> <tr> <td colspan="4"><strong>Term 1</strong></td> </tr> <tr> <td>BSBOPS504</td> <td>Manage Business Risk</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>BSBWHS513</td> <td>Lead WHS risk management</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCBC4001</td> <td>Apply building codes and standards to the construction process for Class 1 and 10 buildings</td> <td>20</td> <td>CORE</td> </tr> <tr> <td>CPCCBC4003</td> <td>Select, prepare and administer a construction contract</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCBC4004</td> <td>Identify and produce estimated costs for building and construction projects</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCBC4012</td> <td>Read and interpret plans and specifications</td> <td>20</td> <td>CORE</td> </tr> <tr> <td colspan="4"><strong>Term 2</strong></td> </tr> <tr> <td>CPCCBC4009</td> <td>Apply legal requirements to building and construction projects</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCBC5013</td> <td>Manage professional technical and legal reports on building and construction projects</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCBC4013</td> <td>Prepare and evaluate tender documentation</td> <td>20</td> <td>CORE</td> </tr> <tr> <td>CPCCBC5019</td> <td>Manage building and construction business finances</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCBC4005</td> <td>Produce labour and material schedules for ordering</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCBC4053</td> <td>Apply building codes and standards to the construction process for Class 2 to 9, Type C buildings</td> <td>20</td> <td>CORE</td> </tr> <tr> <td colspan="4"><strong>Term 3</strong></td> </tr> <tr> <td>CPCCBC4014</td> <td>Prepare simple building sketches and drawings</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCBC4018</td> <td>Apply site surveys and set-out procedures to building and construction projects</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>BSBPMG532</td> <td>Manage project quality</td> <td>40</td> <td>ELECTIVES</td> </tr> <tr> <td>CPCCBC5001</td> <td>Apply building codes and standards to the construction process for Type B construction</td> <td>80</td> <td>CORE</td> </tr> <tr> <td colspan="4"><strong>Term 4</strong></td> </tr> <tr> <td>CPCCBC5002</td> <td>Monitor costing systems on complex building and construction projects</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCBC5007</td> <td>Administer the legal obligations of a building and construction contractor</td> <td>60</td> <td>CORE</td> </tr> <tr> <td>CPCCBC5010</td> <td>Manage construction work</td> <td>60</td> <td>CORE</td> </tr> <tr> <td>CPCCBC4052</td> <td>Lead and manage teams in the building and construction industry</td> <td>40</td> <td>ELECTIVES</td> </tr> <tr> <td colspan="4"><strong>Term 5</strong></td> </tr> <tr> <td>CPCCBC5011</td> <td>Manage environmental management practices and processes in building and construction</td> <td>60</td> <td>CORE</td> </tr> <tr> <td>CPCCBC5004</td> <td>Supervise and apply quality standards to the selection of building and construction materials</td> <td>40</td> <td>ELECTIVES</td> </tr> <tr> <td>CPCCBC4008</td> <td>Supervise site communication and administration processes for building and construction projects</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCBC5003</td> <td>Supervise the planning of onsite building and construction work</td> <td>60</td> <td>CORE</td> </tr> <tr> <td colspan="4"><strong>Term 6</strong></td> </tr> <tr> <td>CPCCBC5005</td> <td>Select and manage building and construction contractors</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCBC4010*</td> <td>Apply structural principles to residential and commercial constructions</td> <td>60</td> <td>CORE</td> </tr> <tr> <td>CPCCBC5018*</td> <td>Apply structural principles to the construction of buildings up to 3 storeys</td> <td>100</td> <td>CORE</td> </tr> </tbody> </table> </div><h4>Pathway</h4><p><strong>Upon completion of the Diploma of Building and Construction (Building), graduates can pursue a wide range of advanced career pathways in the construction industry, including:</strong></p> <ul> <li><strong>Licensed Builder</strong> – Oversee and manage residential or commercial construction projects, ensuring compliance with building codes, safety regulations, and client specifications.</li> <li><strong>Construction Site Manager</strong> – Supervise daily on-site operations, coordinate trades and subcontractors, manage project schedules, and ensure timely project delivery.</li> <li><strong>Project Manager (Construction)</strong> – Plan, execute, and close building projects, managing all aspects including budgeting, procurement, risk assessment, and stakeholder communication.</li> <li><strong>Construction Estimator</strong> – Analyse project plans and specifications to prepare accurate cost estimates and tenders for construction work.</li> <li><strong>Building Inspector</strong> – Assess completed structures to ensure they meet all regulatory, structural, and safety requirements, working with councils or private certification bodies.</li> <li><strong>Contract Administrator</strong> – Manage contracts between builders, suppliers, and clients, ensuring terms and conditions are upheld and documentation is maintained.</li> <li><strong>Site Supervisor</strong> – Lead teams of tradespeople on construction sites, ensuring work is carried out safely, efficiently, and to the required quality standards.</li> </ul> <p>Graduates may also use this qualification as a pathway to meet the educational requirements for builder licensing or registration, depending on local and state legislation.</p> <p> </p>',
    total_course_duration = '78 weeks',
    offshore_tuition_fee = 19500,
    enrolment_fee = 250,
    materials_fee = 1500,
    entry_requirements = '<h4>Entry Requirements</h4><h2><strong>Course Entry Requirements</strong></h2> <p><strong>Training Package Requirements</strong></p> <p>There are no specific prerequisites specified in the training package for this qualification.</p> <p><strong>RTO Requirements for International Students</strong></p> <p>To be eligible for enrolment at APC into the <strong>CPC50220 Diploma of Building and Construction (Building)</strong>, all international applicants must be 18 years old or older and exhibit evidence of academic and English language proficiency as follows:</p> <p><strong>Academic Requirements:</strong></p> <p>✅ Successful completion of Year 12 or equivalent</p> <p><strong>English Language Requirements:</strong></p> <p>✅ Be competent in written and spoken English with an IELTS Score of no less than 6.0 or an equivalent language test score.</p>',
    apply_form = 'https://australianpolytechnic.edu.au/courses/CPC50220 Diploma of Building and Construction (Building)',
    updated_at = NOW()
WHERE cricos_course_code = '117770H';
UPDATE courses SET
    course_description = '<h4>Course Intro</h4><p>This qualification is tailored for those looking to build a career in the construction industry as a qualified carpenter. Throughout the course, you will master the essentials of carpentry, from constructing frameworks and installing fixtures to interpreting plans and working with various building materials. You will also cover important topics like workplace safety, sustainability in construction, and compliance with building codes and regulations.</p> <p>Students will gain skills in carrying out carpentry tasks efficiently, focusing on quality workmanship while maintaining safety and adhering to industry standards. The curriculum also covers teamwork, communication, and problem-solving, preparing students to work effectively on residential and commercial construction sites and collaborate with tradespeople and clients.</p><h4>Course Structure</h4><div> <table cellspacing="0"> <thead> <tr> <td colspan="4"><strong>CPC30220 Certificate III in Carpentry</strong></td> </tr> </thead> <tbody> <tr> <td colspan="4"><strong>TERM 1</strong></td> </tr> <tr> <td>CPCCWHS2001</td> <td>Apply WHS requirements, policies and procedures in the construction industry</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCOM1014</td> <td>Conduct workplace communication</td> <td>20</td> <td>CORE</td> </tr> <tr> <td>CPCCCA3025</td> <td>Read and interpret plans, specifications and drawings for carpentry work</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCWHS3001</td> <td>Identify construction work hazards and select risk control strategies</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCOM3001</td> <td>Perform construction calculations to determine carpentry material requirements</td> <td>20</td> <td>CORE</td> </tr> <tr> <td>CPCCOM1013</td> <td>Plan and organise work</td> <td>40</td> <td>ELECTIVES</td> </tr> <tr> <td colspan="4"><strong>TERM 2</strong></td> </tr> <tr> <td>CPCCCA2002</td> <td>Use carpentry tools and equipment</td> <td>100</td