UPDATE courses SET
    course_description = '<h4>Course Intro</h4><h1>Course Introduction</h1> <p>This qualification is tailored for those looking to build a career in the construction industry as a professional painter and decorator. Throughout the course, you will master the essentials of surface preparation, application of paints and coatings, wallpapering, and decorative finishes across residential and commercial projects. You will also cover important topics like workplace safety, sustainability in painting practices, and compliance with industry regulations and standards.</p> <p>Students will gain skills in performing painting and decorating tasks efficiently, focusing on precision, surface quality, and the correct use of tools and materials. The curriculum also covers teamwork, communication, and problem-solving, preparing students to work effectively on various job sites and collaborate with builders, clients, and other trades.</p> <h4>Course Structure</h4><div> <table cellspacing="0"> <thead> <tr> <td colspan="4"><strong>CPC30620 Certificate III in Painting and Decorating</strong></td> </tr> </thead> <tbody> <tr> <td colspan="4"><strong>Term 1</strong></td> </tr> <tr> <td>CPCCWHS2001</td> <td>Apply WHS requirements, policies and procedures in the construction industry</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCOM1012</td> <td>Work effectively and sustainably in the construction industry</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCOM1013</td> <td>Plan and organise work</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCOM1014</td> <td>Conduct workplace communication</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCOM1015</td> <td>Carry out measurements and calculations</td> <td>40</td> <td>CORE</td> </tr> <tr> <td colspan="4"><strong>Term 2</strong></td> </tr> <tr> <td>CPCCCM3005</td> <td>Calculate costs of construction work</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCOM2001*</td> <td>Read and interpret plans and specifications</td> <td>60</td> <td>CORE</td> </tr> <tr> <td>CPCCPB3026*</td> <td>Erect and maintain trestle and plank systems</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCCM2012</td> <td>Work safely at heights</td> <td>20</td> <td>CORE</td> </tr> <tr> <td>CPCCCM3001</td> <td>Operate elevated work platforms up to 11 metres</td> <td>40</td> <td>CORE</td> </tr> <tr> <td colspan="4"><strong>Term 3</strong></td> </tr> <tr> <td>CPCCCM2008</td> <td>Erect and dismantle restricted height scaffolding</td> <td>80</td> <td>CORE</td> </tr> <tr> <td>CPCCPD2011*</td> <td>Handle and store painting and decorating materials</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCPD2012*</td> <td>Use painting and decorating tools and equipment</td> <td>80</td> <td>CORE</td> </tr> <tr> <td colspan="4"><strong>Term 4</strong></td> </tr> <tr> <td>CPCCPD3031*</td> <td>Work safely with lead-painted surfaces in the painting industry</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCPD3036*</td> <td>Work safely to encapsulate non-friable asbestos in the painting industry</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCPD3021*</td> <td>Prepare existing coated surface for painting</td> <td>60</td> <td>CORE</td> </tr> <tr> <td>CPCCPD3022*</td> <td>Apply paint by brush and roller</td> <td>60</td> <td>CORE</td> </tr> <tr> <td colspan="4"><strong>Term 5</strong></td> </tr> <tr> <td>CPCCPD3025*</td> <td>Match specific paint colours</td> <td>100</td> <td>CORE</td> </tr> <tr> <td>CPCCPD3023*</td> <td>Apply texture coat paint finishes by brush, roller and spray</td> <td>100</td> <td>CORE</td> </tr> <tr> <td colspan="4"><strong>Term 6</strong></td> </tr> <tr> <td>CPCCPD3024*</td> <td>Apply paint by spray</td> <td>100</td> <td>CORE</td> </tr> <tr> <td>CPCCPD3026*</td> <td>Apply stains and clear timber finishes</td> <td>40</td> <td>CORE</td> </tr> <tr> <td>CPCCPD3027*</td> <td>Remove and apply wallpaper</td> <td>60</td> <td>CORE</td> </tr> <tr> <td colspan="4"><strong>Term 7</strong></td> </tr> <tr> <td>CPCCPD3028*</td> <td>Apply decorative paint