UPDATE courses SET
    course_description = '<h4>Course Intro</h4><h3><strong>Description</strong></h3> <p>The Advanced Diploma of Civil Construction Design (RII60520) is designed to give you in-depth knowledge of civil construction design, covering critical areas such as structural integrity, drainage systems, environmental considerations, and project management. The course balances technical training with practical, hands-on experience, ensuring you''re prepared for real-world challenges. With this qualification, you’ll be capable of overseeing and coordinating large-scale civil construction projects from design through to completion.</p> <p>This qualification will equip you to design complex projects that meet client site requirements, while also giving you the technical skills to address challenges and management needs proactively. Your journey at APC will be a key step toward a successful career in civil construction management.</p> <p><strong>Licensing, legislative, regulatory or certification considerations</strong></p> <p>Licensing, legislative, regulatory and certification requirements that apply to this qualification can vary between states, territories and industry sectors. Users must check requirements with relevant body before applying the qualification.</p><h4>Course Structure</h4><h2>RII60520 Advanced Diploma of Civil Construction Design</h2> <table> <tbody> <tr> <th>Unit Code</th> <th>Unit Title</th> <th>Unit Type</th> </tr> <tr> <td>BSBPMG632</td> <td>Manage program risk</td> <td>Core</td> </tr> <tr> <td>BSBWHS616</td> <td>Apply safe design principles to control WHS risks</td> <td>Core</td> </tr> <tr> <td>RIIQUA601E</td> <td>Establish and maintain a quality system</td> <td>Core</td> </tr> <tr> <td>RIICWD601E</td> <td>Manage civil works design processes</td> <td>Core</td> </tr> <tr> <td>RIICWD507D</td> <td>Prepare detailed geotechnical design</td> <td>Elective (Group B)</td> </tr> <tr> <td>RIICWD509E</td> <td>Prepare detailed design of urban roads</td> <td>Elective (Group B)</td> </tr> <tr> <td>RIICWD533E</td> <td>Prepare detailed design of civil concrete structures</td> <td>Elective (Group B)</td> </tr> <tr> <td>BSBTWK502</td> <td>Manage team effectiveness</td> <td>Core</td> </tr> <tr> <td>BSBPMG531</td> <td>Manage project time</td> <td>Elective (Group A)</td> </tr> <tr> <td>BSBSTR601</td> <td>Manage innovation and continuous improvement</td> <td>Elective (Group A)</td> </tr> <tr> <td>RIICWD535E</td> <td>Prepare detailed design of civil timber structures</td> <td>Elective (Group B)</td> </tr> <tr> <td>RIILAT402E</td> <td>Provide leadership in the supervision of diverse work teams</td> <td>Elective (Group B)</td> </tr> </tbody> </table><h4>Pathway</h4><p>Students who complete this course may wish to further their study into a range a range of Graduate Diploma qualifications, as well as higher education qualifications in Civil Construction.</p>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = 26000,
    enrolment_fee = 250,
    materials_fee = 2000,
    entry_requirements = '<h4>Entry Requirements</h4><p>There are no specific pre-requisites specified in the training package for this qualification.</p> <p><strong>RTO Requirements for International Students</strong></p> <p>To be eligible for enrolment at APC into the <strong>RII60520 Advanced Diploma of Civil Construction Design</strong> all international applicants must be 18 years old or older and exhibit evidence of academic and English language proficiency as follows:</p> <p><strong>Academic Requirements:</strong></p> <ul> <li> <p>Students need to have either successfully finished Australian Year 12 or an equivalent level of education, or hold a Certificate IV or a higher qualification from an Australian educational institution.</p> </li> </ul> <p> <strong>Pathway Model:</strong></p> <ul> <li> <p>After completing RII60520 – Advanced Diploma of Civil Construction Design students may progress to higher education courses.</p> </li> </ul> <p><strong>Credit Transfer</strong></p> <ul> <li> <p>We accept qualifications from other RTOs and offer Credit Transfer for equivalent subjects/units.</p> </li> </ul> <p><strong>English Language Requirements:</strong> English Language requirements: Be competent in written and spoken English with an IELTS Score of no less than 6.0 or equivalent language test score.</p>',
    apply_form = 'https://australianpolytechnic.edu.au/courses/advanced-diploma-of-civil-construction-design',
    updated_at = NOW()
