UPDATE courses SET
    course_description = '<h4>Course Intro</h4><p>The Diploma of Civil Construction Design reflects the role of personnel working as designers or design para-professionals who support professional engineers. They perform tasks involving a high level of autonomy and requiring the application of significant judgement in planning and determining the selection of equipment/roles/techniques for themselves and others. They are required to develop site specific work designs to ensure the implementation of the client’s site requirements. They demonstrate the application of a broad range of technical, managerial, coordination and planning skills.</p><h4>Course Structure</h4><h2>RII50520 Diploma of Civil Construction Design</h2> <table> <tbody> <tr> <th>Unit No</th> <th>Unit Code</th> <th>Unit Name</th> <th>Unit Type</th> </tr> <tr> <td>1</td> <td>BSBTWK502</td> <td>Manage team effectiveness</td> <td>Elective (Group A)</td> </tr> <tr> <td>2</td> <td>BSBPMG531</td> <td>Manage project time</td> <td>Elective (Group A)</td> </tr> <tr> <td>3</td> <td>BSBSTR601</td> <td>Manage innovation and continuous improvement</td> <td>Elective (Group A)</td> </tr> <tr> <td>4</td> <td>RIICWD535E</td> <td>Prepare detailed design of civil timber structures</td> <td>Elective (Group C)</td> </tr> <tr> <td>5</td> <td>RIICWD509E</td> <td>Prepare detailed design of urban roads</td> <td>Elective (Group C)</td> </tr> <tr> <td>6</td> <td>RIICWD533E</td> <td>Prepare detailed design of civil concrete structures</td> <td>Elective (Group C)</td> </tr> <tr> <td>7</td> <td>BSBPEF501</td> <td>Manage personal and professional development</td> <td>Elective (Group A)</td> </tr> <tr> <td>8</td> <td>MEM23004A</td> <td>Apply technical mathematics</td> <td>Elective (Group D)</td> </tr> <tr> <td>9</td> <td>RIICWD536E</td> <td>Prepare detailed design of civil masonry</td> <td>Elective (Group C)</td> </tr> <tr> <td>10</td> <td>CPPBDN6106</td> <td>Produce building information modelling for building design projects</td> <td>Elective (Outside)</td> </tr> <tr> <td>11</td> <td>MEM23109</td> <td>Apply engineering mechanics principles</td> <td>Elective (Outside)</td> </tr> <tr> <td>12</td> <td>CPPSIS5032</td> <td>Capture new spatial data</td> <td>Elective (Group D)</td> </tr> <tr> <td>13</td> <td>RIIMPO402D</td> <td>Apply the principles of earthworks construction</td> <td>Elective (Group D)</td> </tr> <tr> <td>14</td> <td>MEM30031A</td> <td>Operate computer-aided design (CAD) system to produce basic drawing elements</td> <td>Elective (Group B)</td> </tr> <tr> <td>15</td> <td>MEM30033A*</td> <td>Use CAD to create and display 3-D models</td> <td>Elective (Group B)</td> </tr> <tr> <td>16</td> <td>MEM30012A</td> <td>Apply mathematical techniques in a manufacturing engineering or related environment</td> <td>Elective (Group D)</td> </tr> <tr> <td>17</td> <td>MEM30006A*</td> <td>Calculate stresses in simple structures</td> <td>Elective (Group D)</td> </tr> <tr> <td>18</td> <td>MEM30005A*</td> <td>Calculate force systems within simple beam structures</td> <td>Elective (Group D)</td> </tr> <tr> <td>19</td> <td>RIICWD504E</td> <td>Prepare detailed design of environmental controls</td> <td>Elective (Group C)</td> </tr> <tr> <td>20</td> <td>RIILAT402E</td> <td>Provide leadership in the supervision of diverse work teams</td> <td>Elective (Group D)</td> </tr> </tbody> </table><h4>Pathway</h4><p>After completing the RII50513 – Diploma of Civil Construction Management, you may progress to higher education courses in civil engineering, construction management, or related fields.</p>',
    total_course_duration = '78 weeks',
    offshore_tuition_fee = 19500,
    enrolment_fee = 250,
    materials_fee = 1500,
    entry_requirements = '<h4>Entry Requirements</h4><p>There are no specific pre-requisites specified in the training package for this qualification. </p> <p><strong>RTO Requirements for International Students </strong></p> <p>To be eligible for enrolment at APC into the BSB80120 Graduate Diploma of Management (Learning) all international applicants must be 18 years old or older and exhibit evidence of academic and English language proficiency as follows:</p> <p><strong>Academic Requirements:</strong></p> <p>✅ Successful completion of Year 12 or equivalent.</p> <p>English Language Requirements:</p> <p>✅ Be competent in written and spoken English with an IELTS Score of no less than 6.0 or equivalent language test score.</p>',
    apply_form = 'https://australianpolytechnic.edu.au/courses/rii50520-diploma-of-civil-construction-design',
    updated_at = NOW()
WHERE cricos_course_code = '118089F';
UPDATE courses SET
    course_description = '<h4>Course Intro</h4><p>The Advanced Diploma of Accounting is a comprehensive qualification covering critical accounting, taxation, and business management areas. This program emphasizes developing the skills to apply accounting principles to various financial and business situations.</p> <p>From preparing financial reports and managing budgets to interpreting financial data for business decision-making, this course is ideal for those wanting to pursue more senior roles in accounting and finance.</p><h4>Course Structure</h4><table cellspacing="0"> <tbody> <tr> <td colspan="2"><strong>FNS60222 - Advanced Diploma of Accounting</strong></td> <td><strong> </strong></td> </tr> <tr> <td><strong>CODE</strong></td> <td><strong>TITLE</strong></td> <td><strong>CORE / ELECTIVE</strong></td> </tr> <tr> <td>FNSACC634</td> <td>Monitor corporate governance activities</td> <td>Core</td> </tr> <tr> <td>FNSINC611</td> <td>Apply economic principles to work in the financial services industry</td> <td>Core</td> </tr> <tr> <td>FNSINC612</td> <td>Interpret and use financial statistics and tools</td> <td>Core</td> </tr> <tr> <td>FNSACC521</td> <td>Provide financial and business performance information</td> <td>Elective</td> </tr> <tr> <td>FNSACC522</td> <td>Prepare tax documentation for individuals</td> <td>Elective</td> </tr> <tr> <td>FNSACC601</td> <td>Prepare and administer tax documentation for legal entities</td> <td>Elective</td> </tr> <tr> <td>FNSACC614*</td> <td>Prepare complex corporate financial reports</td> <td>Elective</td> </tr> <tr> <td>FNSFMK515</td> <td>Comply with financial services regulation and industry codes of practice</td> <td>Elective</td> </tr> <tr> <td>BSBCRT611</td> <td>Apply critical thinking for complex problem solving</td> <td>Elective</td> </tr> <tr> <td>BSBOPS504</td> <td>Manage business risk</td> <td>Elective</td> </tr> <tr> <td>BSBSTR601</td> <td>Manage innovation and continuous improvement</td> <td>Elective</td> </tr> <tr> <td>BSBXCM501</td> <td>Lead communication in the workplace</td> <td>Elective</td> </tr> <tr> <td>BSBTWK503</td> <td>Manage meetings</td> <td>Elective</td> </tr> <tr> <td>BSBTWK601</td> <td>Develop and maintain strategic business networks</td> <td>Elective</td> </tr> </tbody> </table>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = 20000,
    enrolment_fee = 250,
    materials_fee = 1000,
    entry_requirements = '<h4>Entry Requirements</h4><p bis_size=''{"x":20,"y":20,"w":361,"h":41,"abs_x":354,"abs_y":952}''>Prior to commencing this qualification an individual must have completed the following qualifications (or equivalent).</p> <ul bis_size=''{"x":20,"y":74,"w":361,"h":124,"abs_x":354,"abs_y":1006}''> <li bis_size=''{"x":60,"y":74,"w":281,"h":124,"abs_x":394,"abs_y":1006}''><a bis_size=''{"x":60,"y":77,"w":62,"h":14,"abs_x":394,"abs_y":1009}'' href="https://training.gov.au/training/details/FNS50222" target="_self">FNS50222</a> Diploma of Accounting; or its superseded version <a bis_size=''{"x":177,"y":98,"w":62,"h":14,"abs_x":511,"abs_y":1030}'' href="https://training.gov.au/training/details/FNS50217" target="_self">FNS50217</a> Diploma of Accounting or equivalent, provided the listed elective unit <a bis_size=''{"x":132,"y":139,"w":73,"h":14,"abs_x":466,"abs_y":1071}'' href="https://training.gov.au/training/details/BSBTEC402" target="_self">BSBTEC402</a> Design and produce complex spreadsheets (or equivalent) has been completed by those seeking to enrol.</li> </ul>',
    apply_form = 'https://australianpolytechnic.edu.au/courses/advanced-diploma-of-accounting',
    updated_at = NOW()
WHERE cricos_course_code = '112743G';
UPDATE courses SET
    course_description = '<h4>Course Intro</h4><p>This qualification reflects accounting job roles in financial services and other industries, including tax agents, accounts payable and accounts receivable officers, payroll service providers, and employees performing a range of accounting tasks for organisations in a range of industries. Individuals in these roles apply solutions to a range of often complex problems, and analyse and evaluate information from a variety of sources. They apply initiative to plan, coordinate and evaluate their own work and provide guidance to others within defined guidelines.</p> <p><strong>Licensing, legislative, regulatory or certification considerations</strong></p> <p>Work functions in the occupational areas where this qualification may be used are subject to regulatory requirements. Refer to the relevant regulator for specific guidance on requirements.</p> <p>This qualification includes units that comprise an approved Tax Practitioner Board (TPB) course in Australian taxation law and commercial law, which are relevant for registration as a tax agent. Persons seeking registration with the TPB should check current registration requirements with the TPB, as registration requirements are reviewed regularly.</p><h4>Course Structure</h4><table cellspacing="0"> <tbody> <tr> <td colspan="2"><strong>FNS50222 - Diploma of Accounting</strong></td> <td> </td> </tr> <tr> <td><strong>CODE</strong></td> <td><strong>TITLE</strong></td> <td><strong>CORE / ELECTIVE</strong></td> </tr> <tr> <td>BSBTEC402</td> <td>Design and produce complex spreadsheets</td> <td>Core</td> </tr> <tr> <td>FNSACC521</td> <td>Provide financial and business performance information</td> <td>Core</td> </tr> <tr> <td>FNSACC522</td> <td>Prepare tax documentation for individuals</td> <td>Core</td> </tr> <tr> <td>FNSACC523</td> <td>Manage budgets and forecasts</td> <td>Core</td> </tr> <tr> <td>FNSACC524</td> <td>Prepare financial reports for corporate entities</td> <td>Core</td> </tr> <tr> <td>FNSACC526</td> <td>Implement and maintain internal control procedures</td> <td>Core</td> </tr> <tr> <td>FNSACC527</td> <td>Provide management accounting information</td> <td>Core</td> </tr> <tr> <td>BSBLDR413</td> <td>Lead effective workplace relationships</td> <td>Elective</td> </tr> <tr> <td>FNSACC505</td> <td>Establish and maintain accounting information systems</td> <td>Elective</td> </tr> <tr> <td>FNSORG506</td> <td>Prepare financial forecasts and projections</td> <td>Elective</td> </tr> <tr> <td>FNSFMK515</td> <td>Comply with financial services regulation and industry codes of practice</td> <td>Elective</td> </tr> </tbody> </table><h4>Pathway</h4><p>On completion of this course, learners may wish to enrol in further qualifications, FNS60222 Advanced Diploma of Accounting or continue to further university programs.</p>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 10000,
    enrolment_fee = 250,
    materials_fee = 500,
    entry_requirements = '<h4>Entry Requirements</h4><p bis_size=''{"x":20,"y":20,"w":344,"h":62,"abs_x":354,"abs_y":952}''>Prior to commencing this qualification an individual must have completed the following units of competency (or equivalent).</p> <ul bis_size=''{"x":20,"y":95,"w":344,"h":187,"abs_x":354,"abs_y":1027}''> <li bis_size=''{"x":60,"y":95,"w":264,"h":41,"abs_x":394,"abs_y":1027}''><a bis_size=''{"x":60,"y":98,"w":75,"h":14,"abs_x":394,"abs_y":1030}'' href="https://training.gov.au/training/details/FNSACC321" target="_self">FNSACC321</a> Process financial transactions and extract interim reports</li> <li bis_size=''{"x":60,"y":136,"w":264,"h":41,"abs_x":394,"abs_y":1068}''><a bis_size=''{"x":60,"y":139,"w":75,"h":14,"abs_x":394,"abs_y":1071}'' href="https://training.gov.au/training/details/FNSACC322" target="_self">FNSACC322</a> Administer subsidiary accounts and ledgers</li> <li bis_size=''{"x":60,"y":178,"w":264,"h":41,"abs_x":394,"abs_y":1110}''><a bis_size=''{"x":60,"y":181,"w":75,"h":14,"abs_x":394,"abs_y":1113}'' href="https://training.gov.au/training/details/FNSACC418" target="_self">FNSACC418</a> Work effectively in the accounting and bookkeeping industry</li> <li bis_size=''{"x":60,"y":220,"w":264,"h":62,"abs_x":394,"abs_y":1152}''><a bis_size=''{"x":60,"y":222,"w":75,"h":14,"abs_x":394,"abs_y":1154}'' href="https://training.gov.au/training/details/FNSACC421" target="_self">FNSACC421</a> Prepare financial reports (this unit is the equivalent version of <a bis_size=''{"x":74,"y":264,"w":67,"h":14,"abs_x":408,"abs_y":1196}'' href="https://training.gov.au/training/details/BSBFIA401" target="_self">BSBFIA401</a> Prepare financial reports).</li> </ul> <p bis_size=''{"x":20,"y":295,"w":344,"h":41,"abs_x":354,"abs_y":1227}''>These competencies may have been achieved through completion of the following (or their equivalent):</p> <ul bis_size=''{"x":20,"y":350,"w":344,"h":20,"abs_x":354,"abs_y":1282}''> <li bis_size=''{"x":60,"y":350,"w":264,"h":20,"abs_x":394,"abs_y":1282}''><a bis_size=''{"x":60,"y":352,"w":79,"h":14,"abs_x":394,"abs_y":1284}'' href="https://training.gov.au/training/details/FNSSS00014" target="_self">FNSSS00014</a> Accounting Principles Skill Set</li> </ul> <p bis_size=''{"x":20,"y":383,"w":344,"h":20,"abs_x":354,"abs_y":1315}''><strong bis_size=''{"x":20,"y":386,"w":13,"h":14,"abs_x":354,"abs_y":1318}''>or</strong></p> <ul bis_size=''{"x":20,"y":417,"w":344,"h":41,"abs_x":354,"abs_y":1349}''> <li bis_size=''{"x":60,"y":417,"w":264,"h":41,"abs_x":394,"abs_y":1349}''><a bis_size=''{"x":60,"y":420,"w":62,"h":14,"abs_x":394,"abs_y":1352}'' href="https://training.gov.au/training/details/FNS40222" target="_self">FNS40222</a> Certificate IV in Accounting and Bookkeeping.</li> </ul>',
    apply_form = 'https://australianpolytechnic.edu.au/courses/diploma-of-accounting',
    updated_at = NOW()
WHERE cricos_course_code = '112742H';
UPDATE courses SET
    course_description = '<h4>Course Intro</h4><p>This qualification reflects the role of individuals in the accounting and bookkeeping industry, including business activity statement (BAS) agents and contract bookkeepers; and of those employees performing bookkeeping tasks for organisations in a range of industries. It includes preparing and lodging business and instalment activity statements, data processing, monthly reconciliations, preparing budgets, preparing reports on financial performance and the position of the business, preparing end-of-year adjustments, and finalising financial records after year-end. Dealing with the Commissioner of Taxation on behalf of a taxpayer in relation to activity statements and other lodgement matters is also a key component of the role that this qualification reflects. Individuals in these roles apply theoretical and specialist skills and knowledge to work autonomously, and exercise judgement in completing routine and non-routine activities.</p> <p><strong>Licensing, legislative, regulatory or certification considerations</strong></p> <p>Work functions in the occupational areas where this qualification may be used are subject to regulatory requirements. Refer to the relevant regulator for specific guidance on requirements.</p> <p>Persons providing a BAS service for a fee or other reward must be registered by the Tax Practitioners Board (TPB) and this qualification is currently cited as meeting the TPB education requirements for registration as a BAS agent. Other requirements apply, including a designated period of experience. Persons seeking BAS agent registration should check current registration requirements with the TPB, as registration requirements are reviewed regularly.</p><h4>Course Structure</h4><table cellspacing="0"> <tbody> <tr> <td>FNS40222 Certificate IV in Accounting and Bookkeeping</td> </tr> <tr> <td><strong>Core Units</strong></td> </tr> <tr> <td>BSBTEC302 Design and produce spreadsheets</td> </tr> <tr> <td>FNSACC321 Process financial transactions and extract interim reports</td> </tr> <tr> <td>FNSACC322 Administer subsidiary accounts and ledgers</td> </tr> <tr> <td>FNSACC412 Prepare operational budgets</td> </tr> <tr> <td>FNSACC414 Prepare financial statements for non-reporting entities</td> </tr> <tr> <td>FNSACC418 Work effectively in the accounting and bookkeeping industry</td> </tr> <tr> <td>FNSACC421 Prepare financial reports</td> </tr> <tr> <td>FNSACC426 Set up and operate computerised accounting systems</td> </tr> <tr> <td>FNSTPB411 Complete business activity and instalment activity statements</td> </tr> <tr> <td>FNSTPB412 Establish and maintain payroll systems</td> </tr> <tr> <td><strong>Elective Units</strong></td> </tr> <tr> <td>BSBESB402 Establish legal and risk management requirements of new business ventures</td> </tr> <tr> <td>BSBESB403 Plan finances for new business ventures</td> </tr> <tr> <td>BSBESB406 Establish operational strategies and procedures for new business ventures</td> </tr> <tr> <td>BSBOPS304 Deliver and monitor a service to customers</td> </tr> <tr> <td>BSBOPS404 Implement customer service strategies</td> </tr> <tr> <td>BSBPEF501 Manage personal and professional development</td> </tr> <tr> <td>BSBTEC301 Design and produce business documents</td> </tr> <tr> <td>BSBTEC402 Design and produce complex spreadsheets</td> </tr> <tr> <td>BSBTEC404 Use digital technologies to collaborate in a work environment</td> </tr> <tr> <td>BSBWRT311 Write simple documents</td> </tr> <tr> <td>FNSACC323 Perform financial calculations</td> </tr> <tr> <td>FNSACC405 Maintain inventory records</td> </tr> <tr> <td>FNSACC407 Produce job costing information</td> </tr> <tr> <td>FNSACC411 Process business tax requirements</td> </tr> <tr> <td>FNSACC413 Make decisions in a legal context</td> </tr> <tr> <td>FNSACM411 Authorise valid expense payments</td> </tr> <tr> <td>FNSORG506 Prepare financial forecasts and projections</td> </tr> <tr> <td>FNSORG515 Prepare financial reports to meet statutory requirements</td> </tr> <tr> <td>FNSPAY511 Process salary packaging arrangements and additional allowances in payroll</td> </tr> <tr> <td>FNSPAY512 Process superannuation payments in payroll</td> </tr> <tr> <td>FNSPAY513 Process complex employee terminations in payroll</td> </tr> <tr> <td>FNSPAY514 Interpret and apply knowledge of industrial regulations relevant to payroll</td> </tr> <tr> <td>FNSPAY515 Interpret and apply knowledge of taxation systems relevant to payroll</td> </tr> </tbody> </table><h4>Pathway</h4><p>Pathway to further studies</p> <ul> <li>FNS50222 Diploma of Accounting</li> </ul>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 10000,
    enrolment_fee = 250,
    materials_fee = 500,
    entry_requirements = '<h4>Entry Requirements</h4><p>Participants must be at least 18 years of age.</p>',
    apply_form = 'https://australianpolytechnic.edu.au/courses/certificate-iv-in-accounting-and-bookkeeping',
    updated_at = NOW()
WHERE cricos_course_code = '110015M';
UPDATE courses SET
    course_description = '<h4>Course Intro</h4><p><strong>Course Overview</strong></p> <p>This qualification reflects the role of individuals in a variety of information and communications technology (ICT) roles who have significant experience in specialist technical skills, or managerial business and people management skills.</p> <p>Individuals in these roles carry out complex tasks in a specialist field, working independently, leading a team or a strategic direction of a business. They apply their skills across a wide range of industries and business functions, or as a business owner (sole trader/contractor).</p> <p>The skills required for these roles may include, but are not restricted to:</p> <ul> <li>advanced data management information: creating, designing and monitoring complex systems that store data, and optimising organisational knowledge management</li> <li>cyber security: protecting sensitive data and information through security architecture, and developing disaster recovery and contingency plans</li> <li>full stack web development: building advanced user interfaces, developing representational state transfer application program interfaces (REST APIs) and designing user experience solutions</li> <li>further programming: applying advanced ICT languages to maintain security and manage data</li> <li>IT strategy and organisational development: managing and communicating strategic ICT business solutions</li> <li>systems development and analysis: modelling and testing data objects, data processes and preferred ICT system solutions</li> <li>telecommunications network engineering: managing logistics, organisational specifications, regulations and legislative requirements across network projects.</li> </ul> <p>Licensing, legislative, regulatory or certification considerations</p> <p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p><h4>Career Outcomes</h4><p>Take your IT career to the next level with our Advanced Diploma of Information Technology. Master advanced skills in networking, cybersecurity, programming, and IT strategy. Choose from flexible day or evening classes to suit your schedule. Get hands-on with real-world projects and industry placements, totaling up to 360 hours of experience. Build valuable connections with industry professionals and gain the expertise needed to succeed in dynamic, fast-paced IT environments.</p><h4>Course Structure</h4><h2>ICT60220 Advanced Diploma of Information Technology</h2> <table> <tbody> <tr> <th>Unit No</th> <th>Unit Code</th> <th>Unit Name</th> <th>Unit Type</th> </tr> <tr> <td>1</td> <td>BSBXCS402</td> <td>Promote workplace cyber security awareness and best practices</td> <td>Core</td> </tr> <tr> <td>2</td> <td>BSBTWK502</td> <td>Manage team effectiveness</td> <td>Core</td> </tr> <tr> <td>3</td> <td>ICTICT608</td> <td>Interact with clients on a business level</td> <td>Core</td> </tr> <tr> <td>4</td> <td>BSBCRT611</td> <td>Apply critical thinking for complex problem solving</td> <td>Core</td> </tr> <tr> <td>5</td> <td>ICTICT618</td> <td>Manage IP, ethics and privacy in ICT environments</td> <td>Core</td> </tr> <tr> <td>6</td> <td>ICTNPL413</td> <td>Evaluate networking regulations and legislation for the telecommunications industry</td> <td>Elective (G - G)</td> </tr> <tr> <td>7</td> <td>ICTPMG613</td> <td>Manage ICT project planning</td> <td>Elective (G - G)</td> </tr> <tr> <td>8</td> <td>ICTSAD609</td> <td>Plan and monitor business analysis activities in an ICT environment</td> <td>Core</td> </tr> <tr> <td>9</td> <td>ICTTEN615</td> <td>Manage network traffic</td> <td>Elective</td> </tr> <tr> <td>10</td> <td>ICTNWK540</td> <td>Design, build and test network servers</td> <td>Elective</td> </tr> <tr> <td>11</td> <td>ICTNWK541</td> <td>Configure, verify and troubleshoot WAN links and IP services</td> <td>Elective</td> </tr> <tr> <td>12</td> <td>ICTNWK546</td> <td>Manage network security</td> <td>Elective</td> </tr> <tr> <td>13</td> <td>ICTNWK559</td> <td>Install an enterprise virtual computing environment</td> <td>Elective</td> </tr> <tr> <td>14</td> <td>ICTNWK557</td> <td>Configure and manage advanced virtual computing environments</td> <td>Elective</td> </tr> <tr> <td>15</td> <td>ICTTEN622</td> <td>Produce ICT network architecture designs</td> <td>Elective</td> </tr> <tr> <td>16</td> <td>ICTNWK612</td> <td>Plan and manage troubleshooting advanced integrated IP networks</td> <td>Elective</td> </tr> </tbody> </table><h4>Pathway</h4><ul> <li> <p>Bachelor’s degree in Information Technology, Computer Science, or a related field</p> </li> <li> <p>Advanced diplomas or graduate certificates in areas such as Cyber Security, Networking, or Software Development</p> </li> <li> <p>Specialized short courses in Cloud Computing, Data Analytics, or Project Management</p> </li> <li> <p>Professional certifications such as CompTIA, Cisco (CCNA), Microsoft, or AWS</p> </li> </ul>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = 24000,
    enrolment_fee = 250,
    materials_fee = 1000,
    entry_requirements = '<h4>Entry Requirements</h4><p>﻿There are no specific prerequisites specified in the training package for this kitchen management course in Australia. </p> <p><strong>RTO Requirements for International Students </strong></p> <p>To be eligible for enrolment at APC into the Certificate IV in Kitchen Management all international applicants must be 18 years old or older and exhibit evidence of academic and English language proficiency as follows:</p> <p><strong>Academic Requirements:</strong></p> <p>✅ Successful completion of Year 12 or equivalent</p> <p>English Language Requirements:</p> <p>✅ Be competent in written and spoken English with an IELTS Score of no less than 6.0 or equivalent language test score.</p>',
    apply_form = 'https://australianpolytechnic.edu.au/courses/advanced-diploma-of-information-technology',
    updated_at = NOW()
WHERE cricos_course_code = '118090B';
UPDATE courses SET
    course_description = '<h4>Course Intro</h4><p>This course helps you learn English for everyday life, like traveling or living in an English-speaking country. You''ll practice listening, reading, writing, and speaking in a fun and interactive way. The classes get harder as you go, so you can improve your skills and become more confident in English.</p> <p>The course has 6 levels: Beginner, Elementary, Pre-intermediate, Intermediate, Upper Intermediate, and Advanced. Each level lasts 10 weeks, and the whole course takes 60 weeks. You can find more details about what you''ll learn in each level in the course outcomes section.</p><h4>Course Structure</h4><p>Students take a placement test on their first day to find the right English level. We offer six levels of General English classes.</p> <ul> <li>Beginner (Lower Elementary)</li> <li>Elementary</li> <li>Pre-intermediate</li> <li>Intermediate</li> <li>Upper-Intermediate</li> <li>Advanced</li> </ul> <p><strong>Units of Competency</strong></p> <table> <tbody> <tr> <td>Level 1</td> <td>Beginner</td> <td>Term Break of 2 weeks</td> </tr> <tr> <td>Level 2</td> <td>Elementary</td> <td>Term Break of 2 weeks</td> </tr> <tr> <td>Level 3</td> <td>Pre-Intermediate</td> <td>Term Break of 2 weeks</td> </tr> <tr> <td>Level 4</td> <td>Intermediate</td> <td>Term Break of 2 weeks</td> </tr> <tr> <td>Level 5</td> <td>Upper Intermediate</td> <td>Term Break of 2 weeks</td> </tr> <tr> <td>Level 6</td> <td>Advanced</td> <td>Term Break of 2 weeks</td> </tr> </tbody> </table><h4>Pathway</h4><p>Successful completion of this course may allow the student to study other ELICOS courses such as English for Academic Purposes or Vocational Education and Training or Higher Education courses.</p>',
    total_course_duration = '70 weeks',
    offshore_tuition_fee = 17500,
    enrolment_fee = 250,
    materials_fee = 500,
    entry_requirements = '<h4>Entry Requirements</h4><p>There is no specific entry requirement for this ELICOS. This course is available to all international students as along as they can provide the evidence that:</p> <ul> <li>The Student must be 18 years or older at the time of course commencement,</li> <li>The Student has successfully completed the Australian Year 12 (or equivalent) and,</li> <li>AIA Placement Test (if taking the in-between levels) or/</li> <li>Prior to enrolment, students may wish to evidence of prior English knowledge and skills by taking up an assessment to determine which level is the most appropriate for the student. This approach will also allow the us to identify any special needs.</li> <li>Student willing to take the complete General English ELICOS course (all 6 levels), do not require previous knowledge of the English language.</li> </ul> <p>However, for those who do have previous experience, they can submit the results of previous examinations (IELTS or equivalent) to demonstrate their aptitude for the upcoming course, these may also be used for academic purposes.</p>',
    apply_form = 'https://australianpolytechnic.edu.au/courses/general-english-elicos',
    updated_at = NOW()
WHERE cricos_course_code = '116941B';
UPDATE courses SET
    course_description = '<h4>Course Intro</h4><h3><strong>Description</strong></h3> <p>This qualification reflects the role of individuals who apply highly specialised knowledge and skills in the field of organisational learning and capability development. Individuals in these roles generate and evaluate complex ideas. They also initiate, design and execute major learning and development functions within an organisation. Typically, they would have full responsibility and accountability for the personal output and work of others.</p> <p>This qualification may apply to leaders and managers in an organisation where learning is used to build organisational capability. The job roles that relate to this qualification may also include RTO Manager and RTO Director.</p> <p><strong>Licensing/Regulatory Information</strong></p> <p>No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p><h4>Course Structure</h4><table cellspacing="0"> <tbody> <tr> <td><strong>BSB80120 Graduate Diploma of Management (Learning)</strong></td> </tr> <tr> <td><strong>Core Units</strong></td> </tr> <tr> <td>BSBHRM613 Contribute to the development of learning and development strategies</td> </tr> <tr> <td>BSBLDR811 Lead strategic transformation</td> </tr> <tr> <td>TAELED803 Implement improved learning practice</td> </tr> <tr> <td><strong>Elective Units</strong></td> </tr> <tr> <td>BSBCRT611 Apply critical thinking for complex problem solving</td> </tr> <tr> <td>BSBFIN801 Lead financial strategy development</td> </tr> <tr> <td>BSBHRM611 Contribute to organisational performance development</td> </tr> <tr> <td>BSBINS603 Initiate and lead applied research</td> </tr> <tr> <td>BSBLDR601 Lead and manage organisational change</td> </tr> <tr> <td>BSBLDR812 Develop and cultivate collaborative partnerships and relationships</td> </tr> <tr> <td>BSBOPS601 Develop and implement business plans</td> </tr> <tr> <td>BSBSTR801 Lead innovative thinking and practice</td> </tr> <tr> <td>PSPMGT012 Facilitate knowledge management</td> </tr> <tr> <td>TAELED804 Review enterprise e-learning systems and solutions implementation</td> </tr> </tbody> </table><h4>Pathway</h4><p>After completing BSB80120 – Graduate Diploma Of Management (Learning) you may progress to higher education courses.</p>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = 16000,
    enrolment_fee = 250,
    materials_fee = 1000,
    entry_requirements = '<h4>Entry Requirements</h4><p>There are no specific pre-requisites specified in the training package for this qualification. </p> <p><strong>RTO Requirements for International Students </strong></p> <p>To be eligible for enrolment at APC into the BSB80120 Graduate Diploma of Management (Learning) all international applicants must be 18 years old or older and exhibit evidence of academic and English language proficiency as follows:</p> <p><strong>Academic Requirements:</strong></p> <p>✅ Successful completion of Year 12 or equivalent.</p> <p>English Language Requirements:</p> <p>✅ Be competent in written and spoken English with an IELTS Score of no less than 6.0 or equivalent language test score.</p>',
    apply_form = 'https://australianpolytechnic.edu.au/courses/graduate-diploma-of-management-learning',
    updated_at = NOW()
WHERE cricos_course_code = '116940C';
